#!/usr/bin/env node
"use strict";var fs=require("fs"),path=require("path"),imageSize=require(".."),files=process.argv.slice(2);files.length||(console.error("Usage: image-size image1 [image2] [image3] ..."),process.exit(-1));var red=["[31m","[39m"],grey=["[90m","[39m"],green=["[32m","[39m"];files.forEach(function(e){try{if(fs.existsSync(path.resolve(e))){var r=imageSize(e);(r.images||[r]).forEach(function(r){var i=green[0]+r.width+green[1]+grey[0]+"x"+grey[1]+green[0]+r.height+green[1];console.info(i,"-",grey[0]+e+grey[1])})}else console.error("file doesn't exist - ",e)}catch(r){console.error(red[0]+r.message+red[1],"-",e)}});